//! The windows and globals of `app.slint`, generated by slint-build, and the helpers `build.rs` writes from the same
//! declarations. The app (`src/app/`) re-exports them; it is the only code that talks to them.

slint::include_modules!();

/// The split-screen window's copy of the browser's globals (see `src/app/split/mirror.rs`): `sync` and `forward`.
pub mod mirror {
    include!(concat!(env!("OUT_DIR"), "/mirror.rs"));
}

/// The skin tokens (see `src/app/skin/`): every `in-out` property of the `Theme` global with its type, and typed `get` / `set`.
pub mod skin {
    use crate::Theme;
    use slint::{Color, ComponentHandle};

    /// The type of a skin token, by its Slint type.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub enum Ty {
        Color,
        Length,
        Str,
        Int,
        Float,
        Duration,
    }

    /// A token's value, in the Rust type of the Slint property (length: logical px, duration: ms).
    #[derive(Clone, Debug, PartialEq)]
    pub enum Value {
        Color(Color),
        Length(f32),
        Str(String),
        Int(i32),
        Float(f32),
        Duration(i64),
    }

    include!(concat!(env!("OUT_DIR"), "/skin_tokens.rs"));
}
